import fs from 'node:fs';
import vm from 'node:vm';
import assert from 'node:assert/strict';
import {test} from 'node:test';
function context(){
 class Param{value=0;setValueAtTime(v){this.value=v;}setTargetAtTime(v){this.value=v;}cancelScheduledValues(){}}
 class Node{gain=new Param();frequency=new Param();playbackRate=new Param();connect(){return this;}start(){}stop(){}setPeriodicWave(w){this.wave=w;}}
 class AudioContext{currentTime=0;sampleRate=48000;destination={};createPeriodicWave(r,i){return{r,i};}createBuffer(c,size,rate){const data=new Float32Array(size);return{getChannelData:()=>data,duration:size/rate};}createBufferSource(){return new Node();}createBiquadFilter(){return new Node();}}
 const c=vm.createContext({AudioContext,GainNode:Node,OscillatorNode:Node,Float32Array,memory_read:()=>255});vm.runInContext(fs.readFileSync(new URL('../source/papu.js',import.meta.url),'utf8'),c);c.apu_reset();return c;
}
test('envelope restart, divider period, decay, loop and constant volume',()=>{const c=context();c.set_4015(1);c.apu_write(0x4000,1);c.apu_write(0x4003,0);c.apu_quarter();assert.equal(c.apu_channels[0].env,15);c.apu_quarter();assert.equal(c.apu_channels[0].env,15);c.apu_quarter();assert.equal(c.apu_channels[0].env,14);for(let i=0;i<40;i++)c.apu_quarter();assert.equal(c.apu_channels[0].env,0);c.apu_write(0x4000,32);c.apu_channels[0].divider=0;c.apu_quarter();assert.equal(c.apu_channels[0].env,15);c.apu_write(0x4000,31);c.apu_playing=true;c.apu_channels[0].timer=100;c.apu_channels[0].sweep=8;c.apu_render();assert.equal(c.apu_gains[0].gain.value,.08);});
test('sweep negate differs by one for pulse 1/2; divider/reload and overflow mute',()=>{const c=context();for(let ch=0;ch<2;ch++){c.apu_channels[ch].timer=1000;c.apu_channels[ch].sweep=0x89;}c.apu_half();assert.equal(c.apu_channels[0].timer,499);assert.equal(c.apu_channels[1].timer,500);const s=c.apu_channels[0];s.sweep=0x91;s.timer=1000;s.sweepDivider=0;c.apu_half();assert.equal(s.timer,1500);c.apu_half();assert.equal(s.timer,1500);c.apu_playing=true;s.length=5;s.control=31;c.apu_render();assert.equal(c.apu_gains[0].gain.value,0);});
test('length enable/halt and triangle linear reload/control',()=>{const c=context();c.apu_write(0x4003,0);assert.equal(c.apu_channels[0].length,0);c.set_4015(5);c.apu_write(0x4003,0);assert.equal(c.apu_channels[0].length,10);c.apu_half();assert.equal(c.apu_channels[0].length,9);c.apu_write(0x4000,32);c.apu_half();assert.equal(c.apu_channels[0].length,9);c.apu_write(0x4008,2);c.apu_write(0x400b,0);c.apu_quarter();assert.equal(c.apu_channels[2].linear,2);c.apu_quarter();assert.equal(c.apu_channels[2].linear,1);c.set_4015(0);assert.equal(c.get_4015()&15,0);});
test('frame sequencer four/five-step IRQ and acknowledgement',()=>{const c=context();c.apu_clock(29830);assert.ok(c.apu_irq_pending());assert.equal(c.get_4015()&64,64);assert.equal(c.get_4015()&64,0);c.set_4017(128);c.apu_clock(37282);assert.equal(c.apu_irq_pending(),false);c.set_4017(64);c.apu_clock(29830);assert.equal(c.apu_irq_pending(),false);});
test('noise sequences, four pulse duties and pause cancels pending output',()=>{const c=context();assert.equal(c.apu_nodes[3].buffer.getChannelData(0).length,32767);assert.equal(c.apu_nodes[4].buffer.getChannelData(0).length,93);assert.equal(c.apu_waves.length,4);assert.ok(c.apu_waves[0].i[2]>0);assert.ok(Math.abs(c.apu_waves[2].i[2])<1e-6);c.apu_playing=true;c.apu_clock(30000);c.apu_flush();assert.equal(c.apu_gains.length,5);c.apu_playing=false;c.apu_silence();assert.ok(c.apu_gains.every(g=>g.gain.value===0));});


test('DMC PCM buffers and nodes removed',()=>{const c=context();assert.equal(c.apu_gains.length,5);assert.equal(c.apu_sources,undefined);assert.equal(c.apu_pcm,undefined);});

test('DMC MMIO writes ignored, status bits clear, no DMA stalls or DMC IRQ',()=>{const c=context();vm.runInContext(fs.readFileSync(new URL('../source/memory.js',import.meta.url),'utf8'),c);c.set_4017(64);c.set_4015(31);c.cpu_mem=new Uint8Array(65536);c.mapper_write=()=>{};const before=JSON.stringify(c.apu_channels);for(let r=0x4010;r<=0x4013;r++)c.memory_write(r,255);assert.equal(JSON.stringify(c.apu_channels),before);c.memory_read=()=>{throw Error('unexpected DMA');};c.apu_clock(100000);assert.equal(c.get_4015()&144,0);assert.equal(c.apu_irq_pending(),false);assert.equal(c.apu_stalls,undefined);assert.equal(c.apu_dmc,undefined);});
